var n=`0703-dambou`;var s=`world-0703`;var t=`NE`;var o=`western-africa`;var a=4;var r=41;var u={en:`Dambou`,ua:`Дамбу`};var g={en:`Dambou is a Niger classic prepared with couscous, yellow onion, carrot, spinach. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Дамбу, страва кухні країни Нігер зі складниками: кускус, жовта цибуля, морква, шпинат. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var d=[{en:`Steam the moistened grains or processed granules in a covered basket for about 19 minutes; fluff, separate and check tenderness before serving.`,ua:`Пропарте зволожену крупу або готові гранули в закритому кошику приблизно 19 хвилин; розпушіть, розділіть і перевірте м’якість перед подаванням.`,t:[`couscous-steaming`],m:19,i:[[`couscous`,280,`g`],[`water`,390,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,170,`g`],[`carrot`,160,`g`],[`sunflower-oil`,35,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:9,i:[[`spinach`,160,`g`],[`peanut`,75,`g`],[`ground-cumin`,4,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`lemon-juice`,25,`ml`]]}];var m={slug:n,id:s,country:`NE`,region:o,servings:4,minutes:41,title:u,text:g,steps:d};export{t as country,m as default,s as id,r as minutes,o as region,a as servings,n as slug,d as steps,g as text,u as title};